17	  group('WordTtsNotifier pronunciation highlighting', () {
18	    late _FakeWordTtsService tts;
19	    late _FakePronunciationRepository repository;
20	    late _FakeReaderSession session;
21	    late StreamController<Duration> positionController;
22	    late Completer<void> playbackCompleter;
23	    late List<List<String>> playedSequences;
24	    late WordTtsNotifier notifier;
25	
26	    setUp(() {
27	      tts = _FakeWordTtsService();
28	      repository = _FakePronunciationRepository();
29	      session = _FakeReaderSession();
30	      positionController = StreamController<Duration>.broadcast();
31	      playbackCompleter = Completer<void>();
32	      playedSequences = [];
33	      notifier = WordTtsNotifier(
34	        service: tts,
35	        pronunciation: PronunciationPlaybackService.withPlaybackCallbacks(
36	          playPronunciationSequence: (urls) {
37	            playedSequences.add(List<String>.of(urls));
38	            return playbackCompleter.future;
39	          },
40	          stopPronunciation: () async {},
41	          repository: repository,
42	          pronunciationPosition: positionController.stream,
43	        ),
44	        session: session,
45	      )..setBookId('book-1');
46	    });
47	
48	    tearDown(() async {
49	      notifier.dispose();
50	      await positionController.close();
51	      await session.dispose();
52	    });
53	
54	    test(
55	      'builds syllable parts from metadata and advances active index',
56	      () async {
57	        repository.manifest = BookPronunciationManifest(
58	          bookId: 'book-1',
59	          entries: {
60	            'butterfly': const WordPronunciation(
61	              normalizedWord: 'butterfly',
62	              source: 'generated',
63	              syllables: ['but', 'ter', 'fly'],
64	              breakdownSegments: [
65	                PronunciationBreakdownSegment(
66	                  index: 0,
67	                  chunk: 'but',
68	                  spoken: 'but',
69	                  startMs: 0,
70	                  endMs: 250,
71	                ),
72	                PronunciationBreakdownSegment(
73	                  index: 1,
74	                  chunk: 'ter',
75	                  spoken: 'tur',
76	                  startMs: 251,
77	                  endMs: 520,
78	                ),
79	                PronunciationBreakdownSegment(
80	                  index: 2,
81	                  chunk: 'fly',
82	                  spoken: 'fly',
83	                  startMs: 521,
84	                  endMs: 760,
85	                ),
86	              ],
87	              breakdown: PronunciationAudioAsset(
88	                url: 'https://cdn/butterfly-breakdown.mp3',
89	              ),
90	              fullWord: PronunciationAudioAsset(
91	                url: 'https://cdn/butterfly-full.mp3',
92	              ),
93	            ),
94	          },
95	        );
96	
97	        final tapFuture = notifier.onWordTapped('Butterfly!', 12);
98	        await pumpEventQueue();
99	
100	        expect(playedSequences, [
101	          [
102	            'https://cdn/butterfly-breakdown.mp3',
103	            'https://cdn/butterfly-full.mp3',
104	          ],
105	        ]);
106	        expect(notifier.state.tappedWordIndex, 12);
107	        expect(notifier.state.highlightParts.map((part) => part.text), [
108	          'but',
109	          'ter',
110	          'fly',
111	        ]);
112	        expect(notifier.state.highlightParts.map((part) => part.startMs), [
113	          0,
114	          251,
115	          521,
116	        ]);
117	        expect(notifier.state.activeHighlightPartIndex, 0);
118	
119	        positionController.add(const Duration(milliseconds: 300));
120	        await pumpEventQueue();
121	        expect(notifier.state.activeHighlightPartIndex, 1);
122	
123	        positionController.add(const Duration(milliseconds: 700));
124	        await pumpEventQueue();
125	        expect(notifier.state.activeHighlightPartIndex, 2);
126	
127	        // Simulates AudioEngine moving from the breakdown clip to the full-word
128	        // clip, whose position stream restarts from zero.
